```python
BoundFormatValueCallable: TypeAlias = Callable[[Any], Any]

Formatter: TypeAlias = Union[
    Callable[[Any], Any], Callable[[BoundFormatValueCallable, Any], Any]
]

FormatterMapping: TypeAlias = Mapping[type, Formatter]


def _format_list_values(formatter: Formatter, list_value: List[Any]) -> List[Any]:
    """Format a list value using a formatter."""
    return [formatter(e) for e in list_value]


def _format_dict(
    formatter: Formatter,
    dict_value: Dict[str, Any],
) -> Dict[str, Any]:
    """Format a dict value using a formatter."""
    return {k: formatter(v) for k, v in dict_value.items()}


# Default formatters to be used with prompt templates
DEFAULT_PROMPT_FORMATTERS: FormatterMapping = {
    Document: attrgetter("page_content"),
    list: _format_list_values,
    dict: _format_dict,
}


def _identity(x: Any) -> Any:
    """Identity formatter."""
    return x


def _select_formatter(formatter_mapping: FormatterMapping, value: Any) -> Formatter:
    value_type = type(value)
    # First check for exact type match
    if value_type in formatter_mapping:
        return formatter_mapping[value_type]
    # Then check for subclass match
    for type_, formatter in formatter_mapping.items():
        if isinstance(value, type_):
            return formatter

    # Return value as is if no formatter is found
    return _identity


def _apply_formatter(formatter_mapping: FormatterMapping, value: Any) -> Any:
    """Apply a formatter to a value."""
    formatter = _select_formatter(formatter_mapping, value)
    try:
        arity = len(inspect.signature(formatter).parameters)
    except ValueError:
        arity = 1
    if arity == 1:
        _formatter = cast(Callable[[Any], Any], formatter)
        return _formatter(value)
    elif arity == 2:
        prebuilt_formatter = partial(_apply_formatter, formatter_mapping)
        return formatter(prebuilt_formatter, value)
    else:
        raise ValueError(
            f"Formatter {formatter} has too many arguments ({arity}), "
            "expected 1 or 2."
        )
